/// <summary>
/// The class <c>UPSProductPricingAttributeProvider</c> is used to provide <c>UPSPricingAttributeEcoResAttribute</c> associated with product.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
class UPSPricingAttributeProviderCustomerAttribute extends UPSPricingAttributeAbstractProvider implements UPSIPricingAttributeProvider
{
    // Key = attribute name, value = set of allowed values.
    Map allowedValuesMap = new Map(Types::String, Types::AnyType);

}

Method.Source:
/*
 * Header Pricing Attributes (attributes for customer) has data type restrictions.
 */
public Set getPricingAttributes()
{
    RetailParameters parameters;
    EcoResAttribute attributes;
    EcoResAttributeGroup attributeGroup; 
    EcoResAttributeGroupAttribute groupAttributes;
    EcoResAttributeType attributeType;
    UPSEcoResAttributeParameter attributeParameter;

    var attrSet = new Set(Types::AnyType);

    while select Name from attributes
        group by Name
        join TableId from attributeParameter
            where attributes.RecId == attributeParameter.Attribute
            && attributeParameter.IsEnabledAsPricingAttribute == NoYes::Yes
        join Name from attributeType
            group by Name
            where attributes.AttributeType == attributeType.RecId
        join TableId from groupAttributes
            where attributes.RecId == groupAttributes.Attribute
        join TableId from attributeGroup
            where groupAttributes.AttributeGroup == attributeGroup.RecId
        join TableId from parameters
            where parameters.CustomerAttributeGroup == attributeGroup.RecId
    {
        attrSet.add(new UPSPricingAttributeEcoResAttribute(attributes.Name, attributeType.Name, this));
    }

    return attrSet;
}

public anytype getValueOfAttribute(Common _pricingObject, UPSIPricingAttribute _attribute)
{
    SalesTable salesTable;
    CustTable custTable;
    CustomerInstanceValue customerInstanceValue;

    UPSPricingAttributeEcoResAttribute attr = _attribute;

    salesTable = _pricingObject as SalesTable;
    if (salesTable)
    {
        custTable = salesTable.custTable_CustAccount();
    }

    if (custTable)
    {
        select firstonly customerInstanceValue
            where customerInstanceValue.AccountNum == custTable.AccountNum
            && customerInstanceValue.CustomerDataAreaId == custTable.DataAreaId;
    }

    EcoResAttribute ecoResAttribute;
    EcoResAttributeType ecoResAttributeType;
    EcoResAttributeValue ecoResAttributeValue;
    RetailEcoResInstanceAttributeValuesView retailEcoResInstanceAttributeValuesView;

    // join ecoResAttribute and ecoResAttributeType to ensure unique item is found -- key is ecoResAttribute.Name + ecoResAttributeType.Name
    if (customerInstanceValue)
    {
        select firstonly retailEcoResInstanceAttributeValuesView
                where retailEcoResInstanceAttributeValuesView.AttributeDefinitionName == attr.getName()
            join ecoResAttributeValue
                where ecoResAttributeValue.Value == retailEcoResInstanceAttributeValuesView.AttributeValueRecId 
                    && ecoResAttributeValue.InstanceValue == customerInstanceValue.RecId
            join ecoResAttribute
                where ecoResAttribute.RecId == retailEcoResInstanceAttributeValuesView.AttributeDefinitionRecId
            join ecoResAttributeType
                where ecoResAttribute.AttributeType == ecoResAttributeType.RecId 
                    && ecoResAttributeType.Name == attr.getAttributeType();

        return this.extractAttributeValue(retailEcoResInstanceAttributeValuesView, ecoResAttributeType.DataType);
    }

    return '';
}

public Set getAllowedValues(UPSIPricingAttribute _attribute)
{
    UPSPricingAttributeEcoResAttribute attr = _attribute;

    if (attr.isEnumeration())
    {
        return super(_attribute);
    }

    // Attribute with Fixed-list == No.
    // Load all currently existing attribute value, from all customers contain this attribute.

    // Load cache.
    if (allowedValuesMap.exists(this.getAttributeUniqueKey(attr)))
    {
        return allowedValuesMap.lookup(this.getAttributeUniqueKey(attr));
    }

    // Direct query DB.
    EcoResAttribute ecoResAttribute;
    EcoResAttributeType ecoResAttributeType;
    RetailEcoResInstanceAttributeValuesView retailEcoResInstanceAttributeValuesView;

    // Unique key = ecoResAttribute.Name + ecoResAttributeType.Name.
    var ret = new Set(Types::String);
    while select ecoResAttribute
        where ecoResAttribute.Name == attr.getName()
        join ecoResAttributeType
        where ecoResAttribute.AttributeType == ecoResAttributeType.RecId && ecoResAttributeType.Name == attr.getAttributeType()
        join retailEcoResInstanceAttributeValuesView
        where ecoResAttribute.RecId == retailEcoResInstanceAttributeValuesView.AttributeDefinitionRecId
    {
        ret.add(this.extractAttributeValue(retailEcoResInstanceAttributeValuesView, ecoResAttributeType.DataType));
    }

    allowedValuesMap.insert(this.getAttributeUniqueKey(attr), ret);
    return ret;

}

public Query buildPricingObjectQuery(Query _query, UPSIPricingAttribute _pricingAttr, anytype _value, Map _qbdsMap = null)
{
    QueryBuildDataSource qbdsRoot;
    QueryBuildDataSource qbdsCustomerInstance;
    QueryBuildDataSource qbdsEcoResAttributeValue;
    QueryBuildDataSource qbdsRetailEcoResInstanceAttributeValuesView;
    QueryBuildDataSource qbdsEcoResAttribute;
    QueryBuildDataSource qbdsEcoResAttributeType;

    // Find CustTable.
    if (_qbdsMap && _qbdsMap.exists(tableStr(CustTable)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(CustTable));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(CustTable));
        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(CustTable), qbdsRoot);
        }
    }

    // Find CustomerInstanceValue.
    if (_qbdsMap && _qbdsMap.exists(tableStr(CustomerInstanceValue)))
    {
        qbdsCustomerInstance = _qbdsMap.lookup(tableStr(CustomerInstanceValue));
    }
    else
    {
        qbdsCustomerInstance = qbdsRoot.addDataSource(tableNum(CustomerInstanceValue));
        qbdsCustomerInstance.addLink(fieldNum(CustTable, AccountNum), fieldNum(CustomerInstanceValue, AccountNum));
        qbdsCustomerInstance.addLink(fieldNum(CustTable, DataAreaId), fieldNum(CustomerInstanceValue, CustomerDataAreaId));
        qbdsCustomerInstance.joinMode(JoinMode::ExistsJoin);
        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(CustomerInstanceValue), qbdsCustomerInstance);
        }
    }

    // Find EcoResAttributeValue.
    if (_qbdsMap && _qbdsMap.exists(tableStr(EcoResAttributeValue)))
    {
        qbdsEcoResAttributeValue = _qbdsMap.lookup(tableStr(EcoResAttributeValue));
    }
    else
    {
        qbdsEcoResAttributeValue = qbdsCustomerInstance.addDataSource(tableNum(EcoResAttributeValue));
        qbdsEcoResAttributeValue.addLink(fieldNum(CustomerInstanceValue, RecId), fieldNum(EcoResAttributeValue, InstanceValue));
        qbdsEcoResAttributeValue.joinMode(JoinMode::ExistsJoin);
        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(EcoResAttributeValue), qbdsEcoResAttributeValue);
        }
    }

    // Find RetailEcoResInstanceAttributeValuesView.
    qbdsRetailEcoResInstanceAttributeValuesView = qbdsEcoResAttributeValue.addDataSource(tableNum(RetailEcoResInstanceAttributeValuesView));
    qbdsRetailEcoResInstanceAttributeValuesView.addLink(fieldNum(EcoResAttributeValue, Value), fieldNum(RetailEcoResInstanceAttributeValuesView, AttributeValueRecId));
    qbdsRetailEcoResInstanceAttributeValuesView.joinMode(JoinMode::ExistsJoin);

    // Find EcoResAttribute and EcoResAttributeType.
    qbdsEcoResAttribute = qbdsRetailEcoResInstanceAttributeValuesView.addDataSource(tableNum(EcoResAttribute));
    qbdsEcoResAttribute.addLink(fieldNum(RetailEcoResInstanceAttributeValuesView, AttributeDefinitionRecId), fieldNum(EcoResAttribute, RecId));
    qbdsEcoResAttribute.joinMode(JoinMode::ExistsJoin);

    qbdsEcoResAttributeType = qbdsEcoResAttribute.addDataSource(tableNum(EcoResAttributeType));
    qbdsEcoResAttributeType.addLink(fieldNum(EcoResAttribute, AttributeType), fieldNum(EcoResAttributeType, RecId));
    qbdsEcoResAttributeType.joinMode(JoinMode::ExistsJoin);

    // Add range check.
    UPSPricingAttributeEcoResAttribute attr = _pricingAttr;

    QueryBuildRange qbrName = qbdsRetailEcoResInstanceAttributeValuesView.addRange(fieldNum(RetailEcoResInstanceAttributeValuesView, AttributeDefinitionName));
    qbrName.value(any2Str(attr.getName()));

    QueryBuildRange qbrType = qbdsEcoResAttributeType.addRange(fieldNum(EcoResAttributeType, Name));
    qbrType.value(any2Str(attr.getAttributeType()));

    QueryBuildRange qbrValue;
    switch (this.getAttributeType(_pricingAttr.getName()))
    {
        case AttributeDataType::Decimal:
            qbrValue = qbdsRetailEcoResInstanceAttributeValuesView.addRange(fieldNum(RetailEcoResInstanceAttributeValuesView, FloatValue));
            break;
        case AttributeDataType::Integer:
            qbrValue = qbdsRetailEcoResInstanceAttributeValuesView.addRange(fieldNum(RetailEcoResInstanceAttributeValuesView, IntValue));
            break;
        case AttributeDataType::Text:
            var TEST = fieldNum(RetailEcoResInstanceAttributeValuesView, TextValue);
            qbrValue = qbdsRetailEcoResInstanceAttributeValuesView.addRange(fieldNum(RetailEcoResInstanceAttributeValuesView, TextValue));
            break;
        case AttributeDataType::TrueFalse:
            qbrValue = qbdsRetailEcoResInstanceAttributeValuesView.addRange(fieldNum(RetailEcoResInstanceAttributeValuesView, BooleanValue));
            break;
        default:
            // TODO: handle default, error out maybe
            qbrValue = qbdsRetailEcoResInstanceAttributeValuesView.addRange(fieldNum(RetailEcoResInstanceAttributeValuesView, TextValue));
    }
    qbrValue.value(any2Str(_value));

    /* Tester.
    CustTable custTable;
    QueryRun queryRun = new SysQueryRun(_query);
    while (queryRun.next())
    {
        custTable = queryRun.get(tableNum(CustTable));
    }
    */

    return _query;
}

private str extractAttributeValue(RetailEcoResInstanceAttributeValuesView _attrValue, AttributeDataType _dataType)
{
    if (_attrValue)
    {
        switch (_dataType)
        {
            case AttributeDataType::Decimal:
                return num2Str(_attrValue.FloatValue, 0, 3, 1, 2);
            case AttributeDataType::Integer:
                return int642Str(_attrValue.IntValue);
            case AttributeDataType::Text:
                return _attrValue.TextValue;
            case AttributeDataType::TrueFalse:
                return enum2Str(_attrValue.BooleanValue);
            default:
                return '';
        }
    }

    return '';
}
